import test from 'node:test';
import assert from 'node:assert/strict';
import {patchNativeWorkflow,prepareNativeEnvelope,verifyNativeReadback} from './native-workflow.mjs';
const fixture=()=>({unknown:{keep:true},childshapes:[{id:'node',stencil:{id:'SetVariableTask'},properties:{formtype:'current',variablesetting:[{id:'field',type:'text',value:null,extra:1}]},incoming:[],outgoing:[]}],variables:{basic:[{id:'field',type:'text'}]},pageurls:[{id:'page',formdef:{children:[{id:'control',type:'input',binding:'field',label:'Before',attrs:{keep:1}}]}}]});
test('input patch preserves source, identities, attrs and unknown fields',()=>{const d=fixture(),n=patchNativeWorkflow(d,{kind:'inputLabel',pageId:'page',controlId:'control',label:'After'});assert.equal(d.pageurls[0].formdef.children[0].label,'Before');const expected=fixture();expected.pageurls[0].formdef.children[0].label='After';assert.deepEqual(n,expected);});
test('text segments map to native str only',()=>{const n=patchNativeWorkflow(fixture(),{kind:'assignmentText',nodeId:'node',variableId:'field',expression:[{type:'text',value:'Synthetic'}]});assert.deepEqual(n.childshapes[0].properties.variablesetting[0],{id:'field',type:'text',extra:1,value:[{type:'str',value:'Synthetic'}]});});
test('unknown expression and missing binding block',()=>{const c={kind:'assignmentText',nodeId:'node',variableId:'field',expression:[{type:'variable',param:{id:'field'}}]};assert.throws(()=>patchNativeWorkflow(fixture(),c),/TEXT_SEGMENTS_ONLY/);const d=fixture();d.variables.basic=[];assert.throws(()=>patchNativeWorkflow(d,c),/VARIABLE_BINDING_REQUIRED/);});
test('duplicate identity and unsupported patch block',()=>{const d=fixture();d.pageurls.push(d.pageurls[0]);assert.throws(()=>patchNativeWorkflow(d,{kind:'inputLabel',pageId:'page',controlId:'control',label:'x'}),/PAGE_ID_NOT_UNIQUE/);assert.throws(()=>patchNativeWorkflow(fixture(),{kind:'graph'}),/UNSUPPORTED/);});
test('envelope normalizes only verified Int32s and preserves numeric-string ID',()=>{const d={ProcModelID:'9007199254740993',AppID:'41',Status:'0',WorkflowType:'0',unknown:true};assert.deepEqual(prepareNativeEnvelope(d,'codec-output'),{...d,AppID:41,Status:0,WorkflowType:0,DefResource:'codec-output'});assert.throws(()=>prepareNativeEnvelope({...d,Status:''},'x'),/INT32/);});
test('readback mismatch never claims runtime',()=>{assert.deepEqual(verifyNativeReadback(fixture(),fixture()),{persistedReadback:true,designerOpen:false,runtime:false});assert.equal(verifyNativeReadback(fixture(),{}).persistedReadback,false);});
import {validateNativeGraph} from './native-workflow.mjs';
test('native graph accepts Designer string IDs and rejects dangling endpoints',()=>{const d={childshapes:[{id:'s_1',resourceid:'s_1',stencil:{id:'StartNoneEvent'},outgoing:[{id:'s_3',resourceid:'s_3'}]},{id:'s_2',resourceid:'s_2',stencil:{id:'EndNoneEvent'},incoming:[{id:'s_3',resourceid:'s_3'}]},{id:'s_3',resourceid:'s_3',stencil:{id:'SequenceFlow'},source:{id:'s_1',resourceid:'s_1'},target:{id:'s_2',resourceid:'s_2'}}]};assert.equal(validateNativeGraph(d).valid,true);d.childshapes[2].target={x:1,y:2};assert.equal(validateNativeGraph(d).valid,false);});
test('stale node references cannot pass native graph validation',()=>{assert.equal(validateNativeGraph({childshapes:[{id:'n',resourceid:'n',stencil:{id:'EndNoneEvent'},incoming:[{id:'absent',resourceid:'absent'}]}]}).valid,false);});
